import React, { useContext } from 'react';
import { Link } from 'react-router-dom';
import { LanguageContext } from '../context/LanguageContext';

const Footer = () => {
  const { language } = useContext(LanguageContext);

  return (
    <footer className="border-t border-slate-800/60 mt-20">
      <div className="max-w-6xl mx-auto px-6 py-12 grid md:grid-cols-3 gap-10">
        <div>
          <span className="text-lg font-extrabold tracking-tight text-white block mb-4">
            GUARDIAN <span className="bg-gradient-to-r from-blue-400 to-cyan-300 bg-clip-text text-transparent">CYBER LABS</span>
          </span>
          <p className="text-slate-500 text-sm leading-relaxed">
            {language === 'fr'
              ? "Branche formation d'AVALON SECURE — cyberdéfense, réseau et hacking offensif, pensée pour un public international."
              : 'Training branch of AVALON SECURE — cyberdefense, networking and offensive hacking, designed for an international audience.'}
          </p>
        </div>

        <div>
          <h4 className="text-white font-semibold text-sm mb-4 uppercase tracking-wide">
            {language === 'fr' ? 'Navigation' : 'Navigation'}
          </h4>
          <div className="flex flex-col gap-2 text-sm">
            <Link to="/catalog" className="text-slate-500 hover:text-blue-400 transition-colors">{language === 'fr' ? 'Catalogue' : 'Catalog'}</Link>
            <Link to="/about" className="text-slate-500 hover:text-blue-400 transition-colors">{language === 'fr' ? "L'Académie" : 'Academy'}</Link>
            <Link to="/contact" className="text-slate-500 hover:text-blue-400 transition-colors">Contact</Link>
            <Link to="/conditions" className="text-slate-500 hover:text-blue-400 transition-colors">{language === 'fr' ? "Conditions d'utilisation" : 'Terms of use'}</Link>
          </div>
        </div>

        <div>
          <h4 className="text-white font-semibold text-sm mb-4 uppercase tracking-wide">Contact</h4>
          <p className="text-slate-500 text-sm font-mono">avalonsecure7@gmail.com</p>
        </div>
      </div>

      <div className="border-t border-slate-800/60 py-6 text-center">
        <p className="text-slate-600 text-xs">
          © {new Date().getFullYear()} GUARDIAN CYBER LABS — {language === 'fr' ? 'porté par AVALON SECURE. Tous droits réservés.' : 'powered by AVALON SECURE. All rights reserved.'}
        </p>
      </div>
    </footer>
  );
};
export default Footer;
